    # Find the index of planet1 and planet2 in the list
    idx1, idx2 = -1, -1

    for i, planet in enumerate(planets):
        if planet == planet1:
            idx1 = i
        elif planet == planet2:
            idx2 = i

    # If either planet is not found, return an empty tuple
    if idx1 == -1 or idx2 == -1:
        return ()

